import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  TxnOffsetCommit Request (Version: 1) => transactional_id group_id producer_id producer_epoch [topics]
    transactional_id => STRING
    group_id => STRING
    producer_id => INT64
    producer_epoch => INT16
    topics => name [partitions]
      name => STRING
      partitions => partition_index committed_offset committed_metadata
        partition_index => INT32
        committed_offset => INT64
        committed_metadata => NULLABLE_STRING
*/
export function createRequest(transactionalId, groupId, producerId, producerEpoch, _generationId, _memberId, _groupInstanceId, topics) {
    return Writer.create()
        .appendString(transactionalId, false)
        .appendString(groupId, false)
        .appendInt64(producerId)
        .appendInt16(producerEpoch)
        .appendArray(topics, (w, topic) => {
        w.appendString(topic.name, false).appendArray(topic.partitions, (w, partition) => {
            w.appendInt32(partition.partitionIndex)
                .appendInt64(partition.committedOffset)
                .appendString(partition.committedMetadata, false);
        }, false, false);
    }, false, false);
}
/*
  TxnOffsetCommit Response (Version: 1) => throttle_time_ms [topics]
    throttle_time_ms => INT32
    topics => name [partitions]
      name => STRING
      partitions => partition_index error_code
        partition_index => INT32
        error_code => INT16
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        topics: reader.readArray((r, topicIndex) => ({
            name: r.readString(false),
            partitions: r.readArray((r, partitionIndex) => {
                const partition = { partitionIndex: r.readInt32(), errorCode: r.readInt16() };
                if (partition.errorCode !== 0) {
                    errors.push([`/topics/${topicIndex}/partitions/${partitionIndex}`, [partition.errorCode, null]]);
                }
                return partition;
            }, false, false)
        }), false, false)
    };
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(28, 1, createRequest, parseResponse, false, false);
